  "help_cat_getting_started": "Getting Started",
  "help_q_create_account": "How do I create an account?",
  "help_a_create_account": "Click Sign Up in the top navigation, enter your name, email, and password. You'll get a 14-day free trial on any plan — no payment required to start exploring.\",\n          ),\n        },\n        {\n          q: t(\"help_q_first_tree\", \"How do I build my first family tree?",
  "help_a_first_tree": "From your dashboard, choose \\\"New Tree,\\\" add yourself as the first person, then use \\\"Add relative\\\" to add parents, children, and spouses one at a time. You can also import an existing GEDCOM file instead of starting from scratch.\",\n          ),\n        },\n        {\n          q: t(\"help_q_language\", \"Can I use the site in another language?",
  "help_a_language": "Yes — use the language switcher in the navigation bar to change between English, French, Arabic, and Spanish at any time.\",\n          ),\n        },\n      ],\n    },\n    {\n      key: \"trees-gedcom\",\n      icon: Network,\n      title: t(\"help_cat_trees\", \"Family Trees & GEDCOM",
  "help_q_gedcom_import": "What GEDCOM formats can I import?",
  "help_a_gedcom_import": "We support GEDCOM 5.5.1, GEDCOM 7.0, and GEDCOM X (XML, JSON, or .gedx). Use the Import GEDCOM button inside the tree builder toolbar and pick the matching format.\",\n          ),\n        },\n        {\n          q: t(\"help_q_view_vs_download\", \"Why can I view a tree but not download it?",
  "help_a_view_vs_download": "Viewing a tree you don't own renders it read-only in the browser. Downloading the underlying GEDCOM file requires either owning the tree or an approved download request — this protects contributors' research from being copied wholesale without their knowledge.\",\n          ),\n        },\n        {\n          q: t(\"help_q_request_download\", \"How do I request to download someone else's tree?",
  "help_a_request_download": "Open the tree and click \\\"Request to Download.\\\" The owner (or an admin) will be notified and can approve or deny it from their Download Requests page. You can track the status from \\\"My Requests\\\" in the navigation menu.\",\n          ),\n        },\n      ],\n    },\n    {\n      key: \"subscriptions-billing\",\n      icon: CreditCard,\n      title: t(\"help_cat_subscriptions\", \"Subscriptions & Billing",
  "help_q_plans_differ": "How do the plans differ?",
  "help_a_plans_differ": "Basic is free and covers small trees. Premium and Family Historian unlock unlimited trees, archive uploads, GEDCOM import/export, and priority support. See the Subscriptions page for the full feature list.\",\n          ),\n        },\n        {\n          q: t(\"help_q_how_to_pay\", \"How do I pay for a plan?",
  "help_a_how_to_pay": "Choose a plan, then submit a bank transfer using the details shown on the payment page and upload a screenshot of your receipt as proof. Our team reviews and activates it, usually within one business day.\",\n          ),\n        },\n        {\n          q: t(\"help_q_payment_review_time\", \"How long does payment review take?",
  "help_a_payment_review_time": "Most submissions are reviewed within 24 hours. You'll see your plan update automatically once approved — no need to log out and back in.\",\n          ),\n        },\n      ],\n    },\n    {\n      key: \"privacy-data\",\n      icon: Lock,\n      title: t(\"help_cat_privacy\", \"Privacy & Data",
  "help_q_who_sees_tree": "Who can see my family tree?",
  "help_a_who_sees_tree": "You control whether a tree is public or private when you create it. Private trees are visible only to you; public trees appear in the gallery for others to view (and request to download, subject to your approval).\",\n          ),\n        },\n        {\n          q: t(\"help_q_data_rights\", \"What are my data rights?",
  "help_a_data_rights": "Our Privacy Policy covers your rights under GDPR (EU/EEA/UK) and US state privacy laws, including access, correction, deletion, and opting out of data sharing. See the Privacy Policy page for full details.\",\n          ),\n        },\n      ],\n    },\n    {\n      key: \"account-login\",\n      icon: UserCircle2,\n      title: t(\"help_cat_account\", \"Account & Login",
  "help_q_forgot_password": "I forgot my password — what now?",
  "help_a_forgot_password": "Click \\\"Forgot password\\\" on the login page and follow the emailed instructions to set a new one.\",\n          ),\n        },\n        {\n          q: t(\"help_q_delete_account\", \"How do I delete my account?",
  "help_a_delete_account": "Go to My Profile and submit an account deletion request. A super admin reviews and processes these manually to make sure any shared family trees are handled correctly first.\",\n          ),\n        },\n      ],\n    },\n  ];\n}\n\nexport default function HelpCenter() {\n  const { t } = useTranslation();\n  const { theme } = useThemeStore();\n  const isDark = theme === \"dark\";\n  const [query, setQuery] = useState(\"",
