  "help_contact_intro": "Reach out and our team will get back to you.",
  "contact_us": "Contact Us",
  "site_badge": "Roots Tunisia · جذور تونس",
  "start_exploring": "Start Exploring",
  "browse_family_trees": "Browse Family Trees",
  "preserve_lineage_title": "Preserve Your Family Lineage",
  "preserve_lineage_desc": "Connect with your roots, explore historical records, and build a lasting digital legacy for future generations.",
  "why_roots_tunisia_eyebrow": "Why Roots Tunisia",
  "why_roots_tunisia_title": "Tunisian family history needs sources, places and periods together",
  "why_roots_tunisia_intro": "Roots Tunisia is built for families who want evidence without losing memory. It connects état civil extracts, charaïque court sijillat, habous deeds, Protectorate files, photographs, cadastral maps and oral testimony.",
  "why_roots_tunisia_paragraph_2": "A family branch can begin with a modern CIN extract, move into a marriage contract from a Tunis qadi register, connect to a village in the Sahel or the Djérid, and finally sit inside the historical period that produced that record.",
  "primary_evidence_title": "Primary Evidence",
  "primary_evidence_body": "Civil status, sijillat, waqf deeds and ANOM dossiers cited directly on person cards.",
  "territorial_depth_title": "Territorial Depth",
  "territorial_depth_body": "Governorate-level context from Carthage to Djerba, with historical place names.",
  "period_context_title": "Period Context",
  "period_context_body": "Nine eras from Punic antiquity to the contemporary republic to anchor your narrative.",
